const input = $input.first().json;
const resumeId = input.resumeId;
const jdId = input.jdId;
const isValidUuid = (id) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);
return [{
  json: {
    resumeId: resumeId && isValidUuid(resumeId) ? resumeId : "00000000-0000-0000-0000-000000000000",
    jdId: jdId && isValidUuid(jdId) ? jdId : "00000000-0000-0000-0000-000000000000"
  }
}];

const resumeText = $node["Fetch Resume (Combined)"].json.raw_text;
const jdText = $node["Fetch JD (Combined)"].json.raw_text;
const truncate = (text, max) => { if (!text) return ''; return text.length > max ? text.slice(0, max) + '...[truncated]' : text; };
const jdTrimmed = truncate(jdText || 'No job description provided.', 2000);
const resumeTrimmed = truncate(resumeText || 'No resume provided.', 2000);
const prompt = `You are a senior technical recruiter and expert interviewer conducting a pre-interview analysis. Analyze this candidate's resume against the Job Description.

Job Description:
"""
${jdTrimmed}
"""

Candidate Resume:
"""
${resumeTrimmed}
"""

Perform three analyses and return a single combined JSON object matching the exact schema specified below.

ANALYSIS 1: FIT ANALYSIS
- List specific skills, tools, languages, frameworks, or techniques required by the JD or claimed in the resume.
- Classify each as: "match" (required and evidenced), "gap" (required but no evidence), or "strength" (bonus claim not asked in JD).
- Assign priority from 1 (most central to JD) to 5.
- Map 3-4 specific resume projects or experiences to JD requirements.
- Write a 2-3 sentence summary of candidate fit.

ANALYSIS 2: TRUTH AUDIT
- Spot 4-6 specific resume claims that are common targets for exaggeration (vague contribution, missing metrics, team leadership claims).
- For each claim, provide a targeted probe question to verify the experience.
- Write a 1-2 sentence overview of resume credibility.

ANALYSIS 3: DRAFT QUESTIONS (EXACTLY 10 QUESTIONS)
- Generate exactly 10 draft interview questions matching these stages:
  - Q1-3 (Conceptual): Foundational concepts/principles of key tools.
  - Q4-5 (Applied): Practical hands-on scenarios/debugging.
  - Q6-8 (Gaps): Match resume projects against JD requirements, probing gaps.
  - Q9-10 (Cultural fit): Work style, teamwork, collaboration.
- STRICT CEILING: Easy-to-medium practical screening round. Do not ask about distributed systems, scale, framework internals, or low-level memory/algorithms.
- Always explicitly name the specific tool/technology (e.g. "React", "Docker") in the question.

Return ONLY a valid JSON object matching this schema, nothing else:
{
  "fitAnalysis": {
    "skills": [
      { "skill": "string", "source": "jd_required" | "resume_claimed" | "both", "status": "match" | "gap" | "strength", "evidence": "string", "priority": 1 }
    ],
    "projectMappings": [
      { "resumeProject": "string", "relatedJdRequirement": "string", "notes": "string" }
    ],
    "summary": "string"
  },
  "truthAudit": {
    "claims": [
      { "claim": "string", "source": "string", "suspicion_level": "low" | "medium" | "high", "probe_question": "string", "rationale": "string" }
    ],
    "summary": "string"
  },
  "draftQuestions": [
    { "question_text": "string", "question_type": "technical" | "behavioral" | "situational" | "cultural", "strategy": "string" }
  ]
}`;
return [{ json: { prompt } }];
